import{_ as a,C as r,o as c,c as s,aj as n,E as h,j as e,a as d}from"./framework.js";const v=JSON.parse('{"title":"后台菜单总览 | Cms | Documentation","description":"后台菜单总览 in Kooboo: ::: tip 先完成外层步骤 若你仍在 我的站点 列表（/_Admin/），请先阅读 登录与站点列表，点击某一站点的 管理 后再使用下文菜单。 :::","frontmatter":{"title":"后台菜单总览 | Cms | Documentation","description":"后台菜单总览 in Kooboo: ::: tip 先完成外层步骤 若你仍在 我的站点 列表（/_Admin/），请先阅读 登录与站点列表，点击某一站点的 管理 后再使用下文菜单。 :::","head":[["link",{"rel":"canonical","href":"https://docs.kooboo.com/zh/cms/navigation.html"}]]},"headers":[],"relativePath":"zh/cms/navigation.md","filePath":"cms/navigation.md","lastUpdated":1780977342000}'),l={name:"zh/cms/navigation.md"};function i(m,t,p,b,f,g){const o=r("DocImage");return c(),s("div",null,[t[0]||(t[0]=n('<h1 id="后台菜单总览" tabindex="-1">后台菜单总览 <a class="header-anchor" href="#后台菜单总览" aria-label="Permalink to &quot;后台菜单总览&quot;">​</a></h1><blockquote><p>按 Kooboo 站点后台左侧菜单归纳。界面文案以你登录后的中文界面为准。</p></blockquote><div class="tip custom-block"><p class="custom-block-title">先完成外层步骤</p><p>若你仍在 <strong>我的站点</strong> 列表（<code>/_Admin/</code>），请先阅读 <a href="./getting-started/login-and-site-list.html">登录与站点列表</a>，点击某一站点的 <strong>管理</strong> 后再使用下文菜单。</p></div><h2 id="账户级-无-siteid" tabindex="-1">账户级（无 SiteId） <a class="header-anchor" href="#账户级-无-siteid" aria-label="Permalink to &quot;账户级（无 SiteId）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>页面</th><th>路径</th></tr></thead><tbody><tr><td>我的站点</td><td><code>/</code></td></tr><tr><td>登录</td><td><code>/login</code></td></tr><tr><td>新建站点</td><td><code>/create</code></td></tr><tr><td>导入站点</td><td><code>/create/import</code></td></tr><tr><td>克隆站点</td><td><code>/create/clone</code></td></tr><tr><td>文件夹内列表</td><td><code>/?currentFolder={文件夹名}</code></td></tr></tbody></table><p>说明见 <a href="./getting-started/login-and-site-list.html">登录与站点列表</a>、<a href="./getting-started/create-site.html">新建站点</a>。</p><h2 id="站点级深链格式" tabindex="-1">站点级深链格式 <a class="header-anchor" href="#站点级深链格式" aria-label="Permalink to &quot;站点级深链格式&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/_Admin{路由路径}?SiteId={站点GUID}</span></span></code></pre></div><p>将 <code>{站点GUID}</code> 换成地址栏中的 <code>SiteId</code>。下表「路径」均相对于 <code>/_Admin</code>（且需带 <code>SiteId</code>）。</p><h2 id="顶栏与常用入口" tabindex="-1">顶栏与常用入口 <a class="header-anchor" href="#顶栏与常用入口" aria-label="Permalink to &quot;顶栏与常用入口&quot;">​</a></h2><table tabindex="0"><thead><tr><th>入口</th><th>路径</th><th>说明</th></tr></thead><tbody><tr><td>控制面板（首页）</td><td><code>/site</code></td><td>站点概览，见 <a href="./site/dashboard.html">控制面板</a></td></tr><tr><td>媒体库</td><td><code>/site/media</code></td><td>图片与媒体资源，见 <a href="./site/media.html">媒体库</a></td></tr><tr><td>页面</td><td><code>/site/pages</code></td><td>页面列表与编辑，见 <a href="./site/pages.html">页面</a></td></tr></tbody></table><h2 id="内容" tabindex="-1">内容 <a class="header-anchor" href="#内容" aria-label="Permalink to &quot;内容&quot;">​</a></h2><p>左侧分组：<strong>内容</strong>（部分子项需在 <strong>编辑菜单</strong> 中勾选后才显示）</p><table tabindex="0"><thead><tr><th>菜单</th><th>路径</th><th>说明</th></tr></thead><tbody><tr><td>内容</td><td><code>/content/contents</code></td><td>内容夹与条目，对应 <code>k.content.{文件夹名}</code></td></tr><tr><td>数据类型</td><td><code>/content/contentTypes</code></td><td>字段模型，须先于内容夹创建</td></tr><tr><td>标签</td><td><code>/content/labels</code></td><td>多语言文案，对应 <code>k.label</code> / <code>k.t</code></td></tr><tr><td>HTML 片段</td><td><code>/content/htmlblocks</code></td><td>可复用 HTML 块，见 <a href="./content/html-blocks.html">HTML 片段</a></td></tr><tr><td>文件</td><td><code>/content/files</code></td><td>CMS 文件库，见 <a href="./content/files.html">文件</a></td></tr><tr><td>元素属性</td><td><code>/content/text</code></td><td>模板 <code>k-config</code>，见 <a href="./content/tag-attributes.html">元素属性</a></td></tr><tr><td>参数配置</td><td><code>/content/useroptions</code></td><td>结构化站点参数，见 <a href="./content/user-options.html">参数配置</a></td></tr></tbody></table><p>相关文档：<a href="./content/">内容概述</a> · <a href="./content/content-types.html">数据类型</a> · <a href="./content/contents-folders-list.html">内容列表</a> · <a href="./content/labels.html">标签</a> · <a href="./content/html-blocks.html">HTML 片段</a> · <a href="./content/files.html">文件</a> · <a href="./content/tag-attributes.html">元素属性</a> · <a href="./content/user-options.html">参数配置</a></p><h2 id="电商" tabindex="-1">电商 <a class="header-anchor" href="#电商" aria-label="Permalink to &quot;电商&quot;">​</a></h2><p>左侧分组：<strong>电商</strong>（<code>advanced</code>）</p><table tabindex="0"><thead><tr><th>菜单</th><th>路径</th><th>文档</th></tr></thead><tbody><tr><td>商品管理</td><td><code>/commerce/product-management</code></td><td><a href="./commerce/product-management.html">列表</a> · <a href="./commerce/product-management-detail.html">详情</a></td></tr><tr><td>商品类型</td><td><code>/commerce/product-types</code></td><td><a href="./commerce/product-types.html">商品类型</a></td></tr><tr><td>商品分类</td><td><code>/commerce/product-categories</code></td><td><a href="./commerce/product-categories.html">商品分类</a></td></tr><tr><td>购物车</td><td><code>/commerce/carts</code></td><td><a href="./commerce/carts.html">购物车</a></td></tr><tr><td>顾客管理</td><td><code>/commerce/customers</code></td><td><a href="./commerce/customers.html">顾客管理</a></td></tr><tr><td>订单</td><td><code>/commerce/orders</code></td><td><a href="./commerce/orders.html">订单</a></td></tr><tr><td>销售统计</td><td><code>/commerce/sale-stats</code></td><td><a href="./commerce/sale-stats.html">销售统计</a></td></tr><tr><td>优惠折扣</td><td><code>/commerce/discounts</code></td><td><a href="./commerce/discounts.html">优惠折扣</a></td></tr><tr><td>货币</td><td><code>/commerce/currencies</code></td><td><a href="./commerce/currencies.html">货币</a></td></tr><tr><td>配送</td><td><code>/commerce/shippings</code></td><td><a href="./commerce/shippings.html">配送</a></td></tr><tr><td>会员</td><td><code>/commerce/loyalty</code></td><td><a href="./commerce/loyalty.html">会员</a></td></tr><tr><td>税</td><td><code>/commerce/taxes</code></td><td><a href="./commerce/taxes.html">税</a></td></tr><tr><td>通知</td><td><code>/commerce/notification</code></td><td><a href="./commerce/notification.html">通知</a></td></tr><tr><td>设置</td><td><code>/commerce/settings</code></td><td><a href="./commerce/settings.html">设置</a></td></tr></tbody></table><p>概述：<a href="./commerce/">电商</a> · 开发参考：<a href="/kb-docs/zh/api/commerce/commerce.html">k.commerce</a></p><h2 id="运维中心" tabindex="-1">运维中心 <a class="header-anchor" href="#运维中心" aria-label="Permalink to &quot;运维中心&quot;">​</a></h2><p>左侧分组：<strong>运维中心</strong>（路由前缀 <code>/system</code>，与「站点设置」不同分组）</p><table tabindex="0"><thead><tr><th>菜单</th><th>路径</th><th>文档</th></tr></thead><tbody><tr><td>访问统计</td><td><code>/system/visitor-logs</code></td><td><a href="./operations/visitor-logs.html">访问统计</a></td></tr><tr><td>行为分析</td><td><code>/system/user-behavior-analysis</code></td><td>暂未单独成篇</td></tr><tr><td>资源守护</td><td><code>/system/resource-guardian</code></td><td><a href="./operations/resource-guardian.html">资源守护</a></td></tr><tr><td>页面交互</td><td><code>/system/page-interaction</code></td><td><a href="./operations/page-interaction.html">页面交互</a></td></tr><tr><td>AB 测试</td><td><code>/system/ab-testing</code></td><td><a href="./operations/ab-testing.html">AB 测试</a></td></tr><tr><td>错误监控</td><td><code>/system/error-monitoring</code></td><td>暂未单独成篇</td></tr><tr><td>操作日志</td><td><code>/system/site-logs</code></td><td><a href="./operations/site-logs.html">操作日志</a></td></tr><tr><td>协作同步</td><td><code>/system/sync</code></td><td><a href="./operations/sync.html">协作同步</a></td></tr><tr><td>搜索</td><td><code>/system/search</code></td><td>暂未单独成篇</td></tr><tr><td>自动化</td><td><code>/system/automation</code></td><td>暂未单独成篇</td></tr><tr><td>AI 服务</td><td><code>/system/ai-service</code></td><td><a href="./settings/ai-service.html">AI 服务</a></td></tr></tbody></table><p>概述：<a href="./operations/">运维中心</a></p><h2 id="开发" tabindex="-1">开发 <a class="header-anchor" href="#开发" aria-label="Permalink to &quot;开发&quot;">​</a></h2><p>左侧分组：<strong>开发</strong>（<code>advanced</code>）</p><table tabindex="0"><thead><tr><th>菜单</th><th>路径</th><th>文档</th></tr></thead><tbody><tr><td>组件（Views）</td><td><code>/development/views</code></td><td><a href="./development/views.html">组件</a></td></tr><tr><td>布局（Layouts）</td><td><code>/development/layouts</code></td><td><a href="./development/layouts.html">布局</a></td></tr><tr><td>脚本</td><td><code>/development/scripts</code></td><td><a href="./development/scripts.html">脚本</a></td></tr><tr><td>样式</td><td><code>/development/styles</code></td><td><a href="./development/styles.html">样式</a></td></tr><tr><td>代码</td><td><code>/development/code</code></td><td><a href="./development/code.html">代码</a></td></tr><tr><td>代码日志</td><td><code>/development/code-log</code></td><td><a href="./development/code-log.html">代码日志</a></td></tr><tr><td>代码搜索</td><td><code>/development/code-search</code></td><td><a href="./development/code-search.html">代码搜索</a></td></tr><tr><td>URL</td><td><code>/development/urls</code></td><td><a href="./development/urls.html">URL</a></td></tr><tr><td>表单</td><td><code>/development/forms</code></td><td><a href="./development/forms.html">表单</a></td></tr><tr><td>菜单</td><td><code>/development/menus</code></td><td><a href="./development/menus.html">菜单</a></td></tr><tr><td>身份验证</td><td><code>/development/authentication</code></td><td><a href="./development/authentication.html">身份验证</a></td></tr><tr><td>Open API</td><td><code>/development/openapis</code></td><td><a href="./development/openapis.html">Open API</a></td></tr><tr><td>SPA 多语言</td><td><code>/development/spamultilingual</code></td><td><a href="./development/spa-multilingual.html">SPA 多语言</a></td></tr><tr><td>模块</td><td><code>/development/modules</code></td><td><a href="./development/modules.html">模块</a></td></tr><tr><td>定时任务</td><td><code>/development/jobs</code></td><td><a href="./development/jobs.html">定时任务</a></td></tr></tbody></table><p>概述：<a href="./development/">开发</a>（含模板引擎 / API 对照表）</p><div class="info custom-block"><p class="custom-block-title">模块注入的侧栏菜单</p><p>已上线模块可在 <strong><code>module.config</code></strong> 中配置 <strong><code>menu</code></strong>，将自定义入口挂到左侧某一 <strong>顶级分组</strong> 下。<code>parent</code> 填该分组在路由中的 <strong><code>menu.name</code></strong>（如 <code>content</code>、<code>commerce</code>、<code>development</code>、<code>system</code>、<code>database</code>）。详见 <a href="./development/modules.html#挂载站点后台菜单-menu">模块 · 挂载站点后台菜单</a>。</p></div><p>页面设计器路由（无左侧菜单项）：<code>/page/edit</code>、<code>/page/design</code> 等，从 <a href="./site/pages.html">页面</a> 列表进入。</p><h2 id="数据库" tabindex="-1">数据库 <a class="header-anchor" href="#数据库" aria-label="Permalink to &quot;数据库&quot;">​</a></h2><p>左侧分组：<strong>数据库</strong>（<code>advanced</code>）</p><table tabindex="0"><thead><tr><th>菜单</th><th>路径</th><th>文档</th></tr></thead><tbody><tr><td>IndexedDB 表</td><td><code>/database/table</code></td><td><a href="./database/table.html">IndexedDB 表</a></td></tr><tr><td>IndexedDB 表关系</td><td><code>/database/table-relation</code></td><td><a href="./database/table-relation.html">表关系</a></td></tr><tr><td>键值存储</td><td><code>/database/key-value</code></td><td><a href="./database/key-value.html">键值存储</a></td></tr><tr><td>SQLite 表</td><td><code>/database/sqlite-table</code></td><td><a href="./database/sqlite-table.html">SQLite 表</a></td></tr><tr><td>MySQL 表</td><td><code>/database/mysql-table</code></td><td><a href="./database/mysql-table.html">MySQL 表</a></td></tr><tr><td>SQL Server 表</td><td><code>/database/sqlserver-table</code></td><td><a href="./database/sqlserver-table.html">SQL Server 表</a></td></tr><tr><td>SQL 日志</td><td><code>/database/sql-logs</code></td><td><a href="./database/sql-logs.html">SQL 日志</a></td></tr></tbody></table><p>概述：<a href="./database/">数据库</a> · 开发参考：<a href="/kb-docs/zh/api/database/">k.DB</a> · <a href="/kb-docs/zh/api/sqlite/">k.DB.sqlite</a></p><h2 id="站点设置" tabindex="-1">站点设置 <a class="header-anchor" href="#站点设置" aria-label="Permalink to &quot;站点设置&quot;">​</a></h2><p>左侧分组：<strong>站点设置</strong>（同为 <code>/system</code> 前缀，菜单名与「运维中心」不同）</p><table tabindex="0"><thead><tr><th>菜单</th><th>路径</th><th>文档</th></tr></thead><tbody><tr><td>基础设置</td><td><code>/system/settings</code></td><td><a href="./settings/basic/">基础设置</a></td></tr><tr><td>域名管理</td><td><code>/system/domains</code></td><td><a href="./settings/domains.html">域名管理</a></td></tr><tr><td>服务集成</td><td><code>/system/config</code></td><td><a href="./settings/integrations/">服务集成</a></td></tr><tr><td>用户管理</td><td><code>/system/siteuser</code></td><td><a href="./settings/site-users.html">站点用户</a></td></tr><tr><td>角色权限</td><td><code>/system/roles</code></td><td><a href="./settings/roles.html">角色权限</a></td></tr><tr><td>请求 Hook</td><td><code>/system/front-events</code></td><td><a href="./settings/request-hooks.html">请求 Hook</a></td></tr><tr><td>操作 Hook</td><td><code>/system/backend-events</code></td><td><a href="./settings/action-hooks.html">操作 Hook</a></td></tr><tr><td>Cookie 管理</td><td><code>/system/cookie</code></td><td><a href="./settings/cookie.html">Cookie</a></td></tr><tr><td>AI 服务</td><td><code>/system/ai-service</code></td><td><a href="./settings/ai-service.html">AI 服务</a></td></tr></tbody></table><p>概述：<a href="./settings/">站点设置</a> · 集成深链示例：<code>/_Admin/system/config?SiteId=...&amp;group=Payment</code></p><h2 id="独立功能-非左侧主菜单" tabindex="-1">独立功能（非左侧主菜单） <a class="header-anchor" href="#独立功能-非左侧主菜单" aria-label="Permalink to &quot;独立功能（非左侧主菜单）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>功能</th><th>路径</th></tr></thead><tbody><tr><td>AI App Builder</td><td><code>/ai-app-builder</code></td></tr><tr><td>AI Chat</td><td><code>/ai-chat/overview</code></td></tr></tbody></table><h2 id="权限与编辑菜单" tabindex="-1">权限与编辑菜单 <a class="header-anchor" href="#权限与编辑菜单" aria-label="Permalink to &quot;权限与编辑菜单&quot;">​</a></h2><ul><li>子菜单是否可见，还取决于站点角色与功能权限（<code>meta.menu.permission</code>）。</li><li>路由上标有 <code>advanced: true</code> 的项（如 <strong>文件</strong>、<strong>HTML 片段</strong>、<strong>标签属性</strong> 等）默认<strong>不显示</strong>在左侧栏，需要在 <strong>编辑菜单</strong> 里勾选后才会出现。</li></ul><h3 id="如何打开编辑菜单" tabindex="-1">如何打开编辑菜单 <a class="header-anchor" href="#如何打开编辑菜单" aria-label="Permalink to &quot;如何打开编辑菜单&quot;">​</a></h3><ol><li>进入站点后台任意页（如 <a href="./site/dashboard.html">控制面板</a>）。</li><li>点击左侧栏底部的 <strong>编辑菜单</strong>（铅笔图标，<code>editMenu</code>）。</li><li>在弹出面板中勾选或取消各分组下的菜单项；提示文案为「将不常用的菜单隐藏」。</li><li>关闭面板后，左侧菜单立即按你的选择显示或隐藏。</li></ol>',43)),h(o,{src:"/cms/navigation-edit-menu.png",alt:"编辑菜单：勾选要在侧栏显示的内容、站点设置等子项",width:"1120"}),t[1]||(t[1]=e("p",null,[d("勾选 "),e("strong",null,"内容 → 文件"),d("、"),e("strong",null,"HTML 片段"),d(" 等后，即可在左侧 "),e("strong",null,"内容"),d(" 分组下看到对应入口，详见各子文档。")],-1))])}const y=a(l,[["render",i]]);export{v as __pageData,y as default};
